label("$A$", (3.7,0), SE);
label("$B$", (0,0), SW);
label("$C$", (2,4), N);
label("$D$", (2.8,2), NE);
label("$E$", (4.8,2), NE);
label("$F$", (5.3,1.05), SE);
label("$G$", (4.3, 1.05), SE);
[/asy]

